<script setup>
import { ref,computed,watch,onUnmounted } from 'vue';
import { useRoute } from 'vue-router';
import { api } from '../../services/api.js';
import { useStorefront } from '../../services/storefront.js';
import { storefrontSlug, storefrontPath } from '../../services/storeHost.js';
import { StoreCopy } from '../../services/storeCopy.js';
import { StoreTextLayout } from '../../services/storeNavigation.js';
import { CategoryTree } from '../../services/categories.js';
import { sectionSpacing } from '../../services/design.js';
import { money } from '../../services/format.js';
import { notify } from '../../services/notifications.js';
import ProductImage from '../../components/ProductImage.vue';
import ProductCard from '../../components/ProductCard.vue';
import Icon from '../../components/Icon.vue';
const sf=useStorefront(),route=useRoute(),product=ref(null),related=ref([]),recommendations=ref([]),loading=ref(true),error=ref(''),selectedVariant=ref(''),quantity=ref(1),imageIndex=ref(0);
const currentSlug=computed(()=>storefrontSlug(route));
let requestId=0;
const copy=new StoreCopy(()=>sf.design.value);
const design=computed(()=>sf.design.value.product);
const variant=computed(()=>product.value?.variants?.find(v=>v.id===selectedVariant.value));
const price=computed(()=>variant.value?.price??product.value?.price??0);
const stock=computed(()=>variant.value?.stock??product.value?.stock??0);
const available=computed(()=>product.value&&(product.value.type==='digital'||product.value.madeToOrder||(product.value.variants?.length?(variant.value?variant.value.stock>0:product.value.variants.some(v=>v.stock>0)):stock.value>0)));
const needsVariant=computed(()=>product.value?.variants?.length>0&&!variant.value);
const categoryTree=computed(()=>new CategoryTree(sf.categories.value));
const categoryTrail=computed(()=>categoryTree.value.trail(product.value?.categoryId));
const category=computed(()=>categoryTree.value.get(product.value?.categoryId));
function categoryLink(item){const base=sf.link();return {...base,query:{...base.query,categoryId:CategoryTree.id(item)},hash:'#catalogo'};}
async function load(){const seq=++requestId;loading.value=true;error.value='';selectedVariant.value='';quantity.value=1;imageIndex.value=0;try{if(sf.isPreview.value){const item=await sf.getProduct(route.params.id);if(seq!==requestId)return;product.value=item;related.value=sf.products.value.filter(p=>product.value.relatedProductIds?.includes(p._id));recommendations.value=sf.products.value.filter(p=>p._id!==product.value._id).slice(0,3);}else{const data=await api.get(`/public/stores/${currentSlug.value}/products/${route.params.id}`);if(seq!==requestId)return;product.value=data.product;related.value=data.related;recommendations.value=data.recommendations;}document.title=product.value.name+' · '+sf.store.value.name;}catch(e){if(seq===requestId)error.value=e.message;}finally{if(seq===requestId)loading.value=false;}}
function add(){try{sf.cart.value.add(product.value,variant.value,quantity.value);notify.success(`${product.value.name} se agregó a tu carrito.`);}catch(e){notify.error(e.message);}}
async function share(){try{const url=new URL(storefrontPath(route,'/producto/'+product.value._id),location.origin).href;if(navigator.share)await navigator.share({title:product.value.name,url});else{await navigator.clipboard.writeText(url);notify.success('Enlace copiado.');}}catch(e){if(e.name!=='AbortError')notify.info('Podés copiar el enlace desde la barra de direcciones.');}}
watch(()=>route.params.id,load,{immediate:true});onUnmounted(()=>{requestId++;});
</script>
<template><div class="store-product-page store-section" :class="'product-layout-' + design.layout" :style="{...sectionSpacing(design),...StoreTextLayout.style(design.textAlign),'--gallery-cols':design.galleryColumns,'--gallery-mobile-cols':design.galleryMobileColumns}" :dir="StoreTextLayout.direction(design.textDirection)"><div v-if="loading" class="loading"><span class="spinner"></span>Cargando producto…</div><div v-else-if="error" class="store-empty"><h2>Este producto no está disponible.</h2><p>{{error}}</p><RouterLink :to="sf.link()" class="store-button secondary">{{copy.text('backToStore')}}</RouterLink></div><template v-else-if="product"><nav v-if="design.showBreadcrumbs" class="store-breadcrumb product-category-breadcrumb" aria-label="Ruta del producto"><RouterLink :to="sf.link()">{{copy.text('backToStore')}}</RouterLink><template v-for="item in categoryTrail" :key="item._id"><Icon name="chevron-right" :size="14"/><RouterLink :to="categoryLink(item)">{{item.name}}</RouterLink></template><Icon name="chevron-right" :size="14"/><span aria-current="page">{{product.name}}</span></nav><div class="product-detail-grid"><div class="product-gallery" :class="'gallery-'+design.galleryLayout"><div class="product-main-image"><ProductImage :src="product.images?.[imageIndex]" :name="product.name" :type="product.type"/></div><div v-if="product.images?.length>1" class="product-thumbnails"><button v-for="(img,i) in product.images" :key="img" :class="{selected:i===imageIndex}" :aria-label="'Ver imagen '+(i+1)" @click="imageIndex=i"><img :src="img" :alt="product.name+' · '+(i+1)"/></button></div></div><div class="product-detail-info" :style="StoreTextLayout.style(design.textAlign)"><RouterLink v-if="design.showCategory&&category" :to="categoryLink(category)" class="store-eyebrow product-category-link">{{categoryTree.label(category)}}</RouterLink><h1>{{product.name}}</h1><div class="detail-price" :style="{justifyContent:design.textAlign==='center'?'center':design.textAlign==='right'?'flex-end':'flex-start'}"><strong>{{money(price)}}</strong><span v-if="product.previousPrice>price">{{money(product.previousPrice)}}</span></div><h2 v-if="product.description&& copy.text('productDescriptionTitle')" class="product-description-heading">{{copy.text('productDescriptionTitle')}}</h2><div class="product-description">{{product.description}}</div><div v-if="product.type==='digital'" class="store-product-note"><Icon name="mail" :size="18"/><span>{{copy.text('productDigitalNote')}}</span></div><div v-else-if="product.madeToOrder" class="store-product-note"><Icon name="heart" :size="18"/><span>{{design.madeToOrderText}}</span></div><div v-if="product.variants?.length" class="product-variant-selector"><span class="product-variant-label">{{copy.text('productVariantLabel')}}</span><div><button v-for="option in product.variants" :key="option.id" :class="{selected:selectedVariant===option.id}" :disabled="product.type==='physical'&&!product.madeToOrder&&option.stock<=0" @click="selectedVariant=option.id">{{option.name}}<small v-if="option.price!=null&&option.price!==product.price">{{money(option.price)}}</small></button></div></div><p v-if="design.showSku&&variant?.sku" class="store-muted text-sm">{{copy.text('productSku')}}: {{variant.sku}}</p><p v-if="design.showStock && product.type!=='digital' && !product.madeToOrder && (!product.variants?.length||variant)" class="stock-availability" :class="{out:stock<=0}"><span></span>{{stock>0?copy.text('productStock',{count:stock}):copy.text('soldOut')}}</p><div class="product-buy"><div class="quantity-control"><button @click="quantity=Math.max(1,quantity-1)" aria-label="Disminuir cantidad">−</button><input v-model.number="quantity" type="number" min="1" max="99" :aria-label="copy.text('productQuantity')||'Cantidad'" :title="copy.text('productQuantity')||'Cantidad'"/><button @click="quantity=Math.min(99,quantity+1)" aria-label="Aumentar cantidad">+</button></div><button class="store-button" :disabled="!available||needsVariant" @click="add">{{!available?copy.text('soldOut'):needsVariant?copy.text('productVariantLabel'):design.addButton}}<Icon name="cart" :size="18"/></button></div><RouterLink v-if="sf.cart.value.count" :to="sf.link('/carrito')" class="store-view-cart">{{copy.text('productViewCart')}} ({{sf.cart.value.count}}) <Icon name="arrow-right" :size="15"/></RouterLink><div class="product-detail-footer"><span><Icon name="shield" :size="16"/> {{copy.text('productTrust')}}</span><button v-if="design.showShare" @click="share"><Icon name="external-link" :size="15"/>{{copy.text('share')}}</button></div></div></div><section v-if="design.showRelated && related.length" class="store-related"><span class="store-eyebrow">{{copy.text('relatedEyebrow')}}</span><h2>{{design.relatedTitle}}</h2><div class="store-product-grid"><ProductCard v-for="item in related" :key="item._id" :product="item"/></div></section><section v-if="design.showRecommendations && recommendations.length" class="store-related"><span class="store-eyebrow">{{copy.text('recommendationEyebrow')}}</span><h2>{{design.recommendationTitle}}</h2><div class="store-product-grid"><ProductCard v-for="item in recommendations" :key="item._id" :product="item"/></div></section></template></div></template>

<style scoped>
.product-detail-info{min-width:0}.product-description-heading{font-size:.81rem;font-weight:650;letter-spacing:.025em;margin:28px 0 12px}.product-variant-label{display:block;font-size:.79rem;margin-bottom:12px}.product-category-breadcrumb{flex-wrap:wrap;row-gap:8px}.product-category-breadcrumb svg{flex:none}.product-category-breadcrumb a,.product-category-breadcrumb>span{overflow-wrap:anywhere}.product-category-link{width:fit-content}.product-category-link:hover{text-decoration:underline;text-underline-offset:4px}
</style>
